function ensureContactsV13(){
 if(!Array.isArray(Game.contacts))Game.contacts=[];
 for(const d of V13_CONTACTS){
   let c=Game.contacts.find(x=>x.id===d.id);
   if(!c){c={id:d.id,name:d.name,role:d.role,x:-99,y:-99,color:factionColorV13(d.faction),faction:d.faction,missions:[]};Game.contacts.push(c)}
   Object.assign(c,{name:d.name,role:d.role,color:factionColorV13(d.faction),faction:d.faction,sectorId:d.sectorId,v13:true});
   if(!Array.isArray(c.missions))c.missions=[];
 }
}
