function districtCenterV13(sid){
 const s=sectorDefV13(sid);if(!s)return null;const cx=Math.round((s.x0+s.x1)/2),cy=Math.round((s.y0+s.y1)/2);
 let best=null;for(let y=s.y0;y<=s.y1;y++)for(let x=s.x0;x<=s.x1;x++){if(typeof isWalkable==='function'&&!isWalkable(x,y))continue;const d=Math.abs(x-cx)+Math.abs(y-cy);if(!best||d<best.d)best={x,y,d}}return best||{x:cx,y:cy}
}
